u64 get_nested_netlink_attr_offset(u64 ctx, u64 A, u64 X, u64 r4, u64 r5) {
    // Assume that the socket buffer is represented as a byte array.
    // For the sake of this example, we'll assume a helper function to get the buffer and its length.
    void *skb_data = NULL;
    size_t skb_len = 0;

    // Assume a helper function to get the socket buffer data and length from the context.
    if (!get_skb_data_and_length(ctx, &skb_data, &skb_len)) {
        return 0;
    }

    // Validate that the offset A is within the bounds of the socket buffer.
    if (A >= skb_len) {
        return 0;
    }

    // Assume a helper function to get the length of the netlink attribute at offset A.
    size_t attr_len = 0;
    if (!get_netlink_attr_length(skb_data, A, &attr_len)) {
        return 0;
    }

    // Validate that the attribute length is valid.
    if (attr_len == 0 || attr_len > skb_len - A) {
        return 0;
    }

    // Search for the nested attribute of type X within the attribute at offset A.
    u64 nested_offset = 0;
    if (!find_nested_netlink_attr(skb_data, A, attr_len, X, &nested_offset)) {
        return 0;
    }

    // Return the offset of the nested attribute from the start of the socket buffer.
    return nested_offset;
}
